(function(){
  var $=function(id){return document.getElementById(id)};
  // The exact column order Shopify's importer expects.
  var COLS=['Handle','Title','Body (HTML)','Vendor','Type','Tags','Published',
    'Option1 Name','Option1 Value','Option2 Name','Option2 Value','Option3 Name','Option3 Value',
    'Variant SKU','Variant Grams','Variant Inventory Tracker','Variant Inventory Qty',
    'Variant Inventory Policy','Variant Fulfillment Service','Variant Price',
    'Variant Compare At Price','Variant Requires Shipping','Variant Taxable',
    'Image Src','Image Position','Gift Card','Status'];

  function slug(s){
    return String(s).toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'')
      .replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,255);
  }
  function esc(v){
    v=v==null?'':String(v);
    return /[",\n\r]/.test(v) ? '"'+v.replace(/"/g,'""')+'"' : v;
  }
  function list(s){ return String(s).split(',').map(function(x){return x.trim()}).filter(Boolean); }

  function build(){
    var title=$('title').value.trim();
    var handle=$('handle').value.trim()||slug(title);
    var o1n=$('o1n').value.trim(), o1v=list($('o1v').value);
    var o2n=$('o2n').value.trim(), o2v=list($('o2v').value);
    if(!o1v.length){ o1v=['Default Title']; }
    var combos=[];
    o1v.forEach(function(a){
      if(o2n && o2v.length) o2v.forEach(function(b){ combos.push([a,b]) });
      else combos.push([a,'']);
    });
    var status=$('status').value;
    var published = status==='active' ? 'TRUE' : 'FALSE';
    var img=$('img').value.trim();
    var rows=[COLS];
    combos.forEach(function(c,i){
      var first=i===0;
      var r={};
      // Every row carries the handle and its own option values and variant
      // fields. Only the first row of a product carries the product level
      // columns; repeating them on variant rows is what makes an import
      // create several products instead of one with variants.
      r['Handle']=handle;
      r['Title']=first?title:'';
      r['Body (HTML)']=first?$('body').value:'';
      r['Vendor']=first?$('vendor').value:'';
      r['Type']=first?$('type').value:'';
      r['Tags']=first?list($('tags').value).join(', '):'';
      r['Published']=first?published:'';
      r['Option1 Name']=first?(o1n||'Title'):'';
      r['Option1 Value']=c[0];
      r['Option2 Name']=first?(o2n&&o2v.length?o2n:''):'';
      r['Option2 Value']=c[1];
      r['Option3 Name']=''; r['Option3 Value']='';
      var pre=$('sku').value.trim();
      r['Variant SKU']= pre ? [pre, slug(c[0]).toUpperCase(), c[1]?slug(c[1]).toUpperCase():''].filter(Boolean).join('-') : '';
      r['Variant Grams']=$('grams').value||'0';
      r['Variant Inventory Tracker']='shopify';
      r['Variant Inventory Qty']=$('qty').value||'0';
      r['Variant Inventory Policy']='deny';
      r['Variant Fulfillment Service']='manual';
      r['Variant Price']=(+$('price').value||0).toFixed(2);
      var cp=$('cprice').value;
      r['Variant Compare At Price']= cp!=='' ? (+cp).toFixed(2) : '';
      r['Variant Requires Shipping']='TRUE';
      r['Variant Taxable']='TRUE';
      r['Image Src']=first&&img?img:'';
      r['Image Position']=first&&img?'1':'';
      r['Gift Card']=first?'FALSE':'';
      r['Status']=first?status:'';
      rows.push(COLS.map(function(k){ return r[k]===undefined?'':r[k] }));
    });
    var csv=rows.map(function(r){ return r.map(esc).join(',') }).join('\r\n');
    $('out').textContent=csv;
    $('nvar').textContent=combos.length;
    $('nrow').textContent=rows.length-1;
    $('nhandle').textContent=handle||'not set';
    var warn=[];
    if(!title) warn.push('Add a title, otherwise the import has nothing to name the product.');
    if(combos.length>100) warn.push('Shopify allows 100 variants per product; this has '+combos.length+'.');
    if($('handle').value.trim() && $('handle').value.trim()!==slug($('handle').value))
      warn.push('Handles must be lowercase letters, numbers and hyphens only. Yours will be corrected on import.');
    if(img && !/^https?:\/\//i.test(img)) warn.push('The image URL needs to start with http or https and be reachable publicly.');
    $('note').textContent= warn.length ? warn.join(' ')
      : combos.length+' variant'+(combos.length>1?'s':'')+' across '+(rows.length-1)+' rows. Only the first row carries the product details, which is what keeps this as one product rather than '+combos.length+'.';
    if(window.WT) WT.resize();
    return csv;
  }
  ['title','handle','vendor','type','body','tags','status','o1n','o1v','o2n','o2v',
   'price','cprice','sku','qty','grams','img'].forEach(function(id){
    $(id).addEventListener('input',build); $(id).addEventListener('change',build);
  });
  $('dl').addEventListener('click',function(){
    var csv=build();
    // the BOM keeps accented characters intact when the file is opened in Excel
    var b=new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'});
    var u=URL.createObjectURL(b),a=document.createElement('a');
    a.href=u; a.download=(slug($('title').value)||'products')+'.csv';
    document.body.appendChild(a); a.click();
    setTimeout(function(){URL.revokeObjectURL(u);a.remove()},4000);
  });
  $('copy').addEventListener('click',function(){
    var ok=WT.copy(build());
    this.textContent=ok?'Copied':'Press Ctrl+C';
    var b=this; setTimeout(function(){b.textContent='Copy CSV'},1400);
  });
  build();
})();
